INSERT INTO `board_news` (`id`, `title`, `content`, `writer`, `password`, `source`, `source_url`, `attachment`, `view_count`, `created_at`, `updated_at`) VALUES ('1', '철강 가격 동향 및 전망', '최근 국제 철강 가격이 상승세를 보이고 있습니다.\n\n중국의 생산 감축과 원자재 가격 상승이 주요 원인으로 분석됩니다.', '관리자', '1234', '한국철강신문', NULL, NULL, '271', '2025-08-05 01:52:35', '2026-02-05 13:10:39');
INSERT INTO `board_news` (`id`, `title`, `content`, `writer`, `password`, `source`, `source_url`, `attachment`, `view_count`, `created_at`, `updated_at`) VALUES ('2', '친환경 철강 생산 기술 개발', '포스코가 수소환원제철 기술 개발에 성공했다고 발표했습니다.\n\n이를 통해 탄소 배출을 획기적으로 줄일 수 있을 것으로 기대됩니다.', '관리자', '1234', '철강업계뉴스', NULL, NULL, '215', '2025-08-05 01:52:35', '2026-02-06 03:24:34');
INSERT INTO `board_news` (`id`, `title`, `content`, `writer`, `password`, `source`, `source_url`, `attachment`, `view_count`, `created_at`, `updated_at`) VALUES ('15', '[신년사] \"동심만리 마음으로 동반성장 지혜 찾길\"', '<p><img src=\"/uploads/news/news_20260114065113_69673ce118ae6.jpg\" style=\"max-width: 100%; height: auto;\"><br></p>', 'admin', '', '', '', NULL, '144', '2026-01-14 06:54:35', '2026-02-05 20:37:18');
INSERT INTO `board_news` (`id`, `title`, `content`, `writer`, `password`, `source`, `source_url`, `attachment`, `view_count`, `created_at`, `updated_at`) VALUES ('16', '[신년사] 충남스틸 “동심만리의 한 마음으로 상생·도약”', '<p><img src=\"/uploads/news/news_20260114070712_696740a0282a3.jpg\" style=\"max-width: 100%; height: auto;\"><br></p>', 'admin', '', '', '', NULL, '139', '2026-01-14 07:08:09', '2026-02-05 13:10:02');
