INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('159', '제품 견적 문의', '안녕하세요.\r\n\r\n제품 구입 견적 문의드립니다.\r\n\r\n1. H-BEAM \r\n    1). H150*150*7*10  = 1612kg\r\n    2). H200*100*5.5*8 = 1122kg\r\n    3). H250*125*6*9    = 1432kg\r\n2. C-CHANNEL\r\n    1). 100*50*20*2.3    = 406kg\r\n    2). 100*50*20*3.2    = 1420kg\r\n\r\n3. SQ-PIPE\r\n    1). 100*100*3.2       = 350kg\r\n\r\n4. R-BAR\r\n    1). 파이19               = 321kg\r\n\r\n운반비까지 포함인지 궁금합니다.\r\n\r\n감사합니다.', '하헌록', '3530', '개인사업자', 'haheonrok@gmail.com', '010-8109-4882', '', '5', '0', NULL, NULL, '2026-01-19 04:11:53', '2026-01-19 04:12:35', NULL);
