INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('161', '아연각관 견적 문의합니다.', '아연각관 소매업을 하려합니다. \r\n견적 금액 부탁드립니다.\r\n20*40 1.4\r\n50*50 1.4\r\n50*50 2.0\r\n100*50 2.0\r\n100*100 2.0\r\n100*100 2.9 입니다.', '고태범', 'tb061500', '우송건축자재', 'sinan8204@naver.com', '010-9938-9882', '', '0', '0', NULL, NULL, '2026-01-28 00:37:07', '2026-01-28 00:37:07', NULL);
INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('162', '견적 부탁 드립니다.', '안녕하세요?\r\n추운 날씨에 고생 많으십니다.\r\n저희는 태양광 구조물 제작, 시공 전문 업체입니다.\r\n아연각관 (100*100*2.3t), 수량 : 200본\r\nC형강 (100*50*20*2.3t), 수량 : 200본\r\n견적 부탁드립니다.\r\n그리고 운송은 어떻게 되는지도 부탁드립니다.\r\n감사합니다. ', '정양수', '402501', '주식회사 씨알', 'e1energy@naver.com', '010-2656-5100', '', '1', '0', NULL, NULL, '2026-01-30 00:36:24', '2026-01-30 00:37:25', NULL);
